import { scryptAsync as scryptAsyncNoble } from '@noble/hashes/scrypt.js'
import { assertEmptyRest, assertInteger } from './utils/assertUint8.mjs'
import { fromUint8orString } from './utils/input.mjs'
import { assertOutputFormat, fromUint8Super } from './utils/output.mjs'

// N is required, everything else is optional and set to common defaults

export async function scrypt(input, salt, { N, r = 8, p = 1, dkLen = 32, ...w }, format = 'uint8') {
  assertEmptyRest(w)
  assertOutputFormat(format) // Early check, this is rechecked later in fromUint8Super

  // Noble accepts p=0 and disagrees with Node.js on that (in Node.js, p=0 means default p=1)
  // dkLen = 0 makes no sense
  // Other values can't be 0 and are rechecked by noble, but we recheck either way
  assertInteger(N, 'N', 2)
  assertInteger(r, 'r', 1)
  assertInteger(p, 'p', 1)
  assertInteger(dkLen, 'dkLen', 1)

  input = fromUint8orString(input, 'input') // eslint-disable-line no-param-reassign
  salt = fromUint8orString(salt, 'salt') // eslint-disable-line no-param-reassign
  if (!(salt.length > 0)) throw new Error('Zero-length salt is not supported')

  return fromUint8Super(await scryptAsyncNoble(input, salt, { N, r, p, dkLen }), format)
}

// Sync version can cause UX issues, it will block the thread
// We don't have it exposed atm
